import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const tragedyPhysicalScenarios=['tragedy-gainas','tragedy-dia','tragedy-hidden','tragedy-unrelated','tragedy-multi','tragedy-late','tragedy-late-death','tragedy-counter','tragedy-follower','tragedy-third','tragedy-canceled','tragedy-refill'] as const;
export type TragedyPhysicalScenario=typeof tragedyPhysicalScenarios[number];
export function isTragedyPhysicalScenario(name:string):name is TragedyPhysicalScenario{return (tragedyPhysicalScenarios as readonly string[]).includes(name);}
export function tragedyMode(name:TragedyPhysicalScenario){const late=name==='tragedy-late'||name==='tragedy-late-death',multi=late||name==='tragedy-multi'||name==='tragedy-counter',follower=name==='tragedy-follower'||name==='tragedy-third',third=late||name==='tragedy-third'||name==='tragedy-counter';return{late,multi,follower,third,owner:third?3:1,attack:multi?'a2-p10-r2c1':'a2-p10-r1c3'};}
/** Actual setup, reveal, chant and complete prior turns; attack is not started or effect injected. */
export function makeTragedyPhysicalScenario(name:TragedyPhysicalScenario,players:{id:string;name:string}[]){
 let s=createGame(players,entropy(),{startingSeat:0});const m=tragedyMode(name),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[name==='tragedy-dia'?'魔聖母ディア':name==='tragedy-unrelated'?'黒騎士ガーウィン':'魔導王ガイナス',name==='tragedy-counter'?'早駆けのランカスター':'聖騎士ランスロット','大神官ジル','侍大将のシン'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};
 if(name==='tragedy-late-death')s.players[b]!.damage=gameStats(s,b).endurance-15;
 const keep=[takeCard(s,a,m.attack),takeCard(s,a,'a2-p24-r1c2'),takeCard(s,a,'a2-p02-r2c3'),takeCard(s,players[m.owner]!.id,'a2-p01-r2c3'),takeCard(s,b,'閃光槍')];if(m.follower)keep.push(takeCard(s,b,'a2-p20-r3c1'));for(const p of players)trimHand(s,p.id,...keep);
 let blood:string|undefined;if(name==='tragedy-refill'){blood=takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open');const prefix=players.reduce((n,p)=>n+Math.max(0,5-s.players[p.id]!.hand.length),0)+1;s.deck=blood?[...ordinary.slice(0,prefix),blood,...ordinary.slice(prefix),...opens]:[...ordinary,...opens];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`TRAGEDY_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('TRAGEDY_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('TRAGEDY_FIXTURE_CARDS');}
 for(const id of [a,b,c,d]){if(id===b&&m.follower)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p20-r3c1'});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(name!=='tragedy-hidden')act(a,{type:'REVEAL_CHARACTER'});act(a,{type:'CHANT',cardInstanceId:m.attack});
 for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(id=>!keep.includes(id)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('TRAGEDY_FIXTURE_PHASE');}
 if(s.phase!=='action'||s.seatOrder[s.turnSeat]!==a)throw Error('TRAGEDY_FIXTURE_TURN');if(blood&&s.deck[0]!==blood)throw Error('TRAGEDY_REFILL_PREFIX');return s;
}
